// Import page-specific translations
import { pageTranslations } from './translationsPages';

// Hook to use translations (merges base + page translations + extras)
import { translationsExtra } from './translationsExtra';

export const useTranslation = (lang = 'en') => {
  const t = (key) => {
    return (
      translations[lang]?.[key] ||
      pageTranslations[lang]?.[key] ||
      translationsExtra[lang]?.[key] ||
      translations['en']?.[key] ||
      pageTranslations['en']?.[key] ||
      translationsExtra['en']?.[key] ||
      key
    );
  };
  
  return { t };
};

